struct Invoice {
    private(set) var lines: [Line]
    let currency: Currency

    mutating func add(_ line: Line) throws {          // value concept, in-place mutation
        guard line.currency == currency else { throw InvoiceError.currencyMismatch }
        lines.append(line)
    }
    var total: Money { lines.reduce(.zero) { $0 + $1.amount } }
}
